class AsyncTeamResource:
    def __init__(self, http: HttpClient):
        self._http = http
        self.artifacts = AsyncTeamArtifactResource(http)
        self.custom_objects = AsyncTeamCustomObjectResource(http)
        self.members = AsyncMemberResource(http)
        self.threads = AsyncTeamThreadResource(http)

    async def list(
        self,
        *,
        page: int | None = None,
        page_size: int | None = None,
        search: str | None = None,
        metadata: dict[str, Any] | None = None,
        membership: str | None = None,
    ) -> TeamListResponse:
        query: dict[str, object] = {}
        if page is not None:
            query["page"] = page
        if page_size is not None:
            query["pageSize"] = page_size
        if search is not None:
            query["search"] = search
        if metadata is not None:
            query["metadata"] = metadata
        if membership is not None:
            query["membership"] = membership
        return await self._http.request(
            "/api/v1/teams",
            query=query,
            response_type=TeamListResponse,
        )

    async def create(self, input: TeamCreateInput) -> Team:
        return await self._http.request(
            "/api/v1/teams",
            method="POST",
            body=input,
            response_type=Team,
        )

    async def join_by_code(self, input: TeamJoinByCodeInput) -> Team:
        """
        Join a team using an invite code
        Accepts either `join_code` or `invite_code`.
        For user-authenticated requests, the current user joins the team identified by
        the invite code. For server-to-server requests, provide `agent` or `user` to
        add that principal to the team instead.
        """
        return await self._http.request(
            "/api/v1/teams/join_by_code",
            method="POST",
            body=input,
            response_type=Team,
        )

    async def delete(self, team: str) -> None:
        await self._http.request(f"/api/v1/teams/{team}", method="DELETE")

    async def get(self, team: str) -> Team:
        return await self._http.request(f"/api/v1/teams/{team}", response_type=Team)

    async def update(self, team: str, input: TeamUpdateInput) -> Team:
        return await self._http.request(
            f"/api/v1/teams/{team}",
            method="PATCH",
            body=input,
            response_type=Team,
        )

    async def invite(self, team: str) -> TeamInvite:
        return await self._http.request(
            f"/api/v1/teams/{team}/invite",
            method="POST",
            response_type=TeamInvite,
        )

    async def invites(self, team: str) -> TeamInvitesResponse:
        return await self._http.request(
            f"/api/v1/teams/{team}/invites",
            method="POST",
            response_type=TeamInvitesResponse,
        )

    async def join(self, team: str, input: TeamJoinInput) -> None:
        """
        Join a team the current user can see
        Joins a specific visible team by team ID.
        For standard user requests, the current user is added to the team. When
        `agent` is provided, the current user must already be a team member and the
        agent is added instead. When `user` is provided, the current user must be
        able to manage the team (owner / team admin / org admin) and the named user,
        who must belong to the caller's own org, is added as a member.
        """
        await self._http.request(f"/api/v1/teams/{team}/join", method="POST", body=input)

    async def leave(self, team: str) -> None:
        await self._http.request(f"/api/v1/teams/{team}/leave", method="DELETE")


